# Game status categories
# Change the values as you see fit
STATUS_WIN = 'win'
STATUS_LOSE = 'lose'
STATUS_ONGOING = 'ongoing'


class Hangman:
    # The game allows this many failures before the player loses.
    MAX_FAILURES = 10

    def __init__(self, word):
        self._word = word
        # The only mutable state: the stream of guesses, in order.
        # Everything else (masked word, status, remaining guesses)
        # is derived from this stream, FRP style.
        self._guesses = []

    def guess(self, char):
        if self.get_status() != STATUS_ONGOING:
            raise ValueError("The game has already ended.")
        self._guesses.append(char)

    def get_masked_word(self):
        return ''.join(
            char if char in self._correct_letters else '_'
            for char in self._word
        )

    def get_status(self):
        if all(char in self._correct_letters for char in self._word):
            return STATUS_WIN
        if self._failures >= self.MAX_FAILURES:
            return STATUS_LOSE
        return STATUS_ONGOING

    @property
    def remaining_guesses(self):
        return max(0, self.MAX_FAILURES - 1 - self._failures)

    @property
    def _correct_letters(self):
        # Letters of the word that have been guessed at least once.
        return {char for char in self._guesses if char in self._word}

    @property
    def _failures(self):
        # A guess fails when the letter is not in the word, or when it
        # is in the word but has already been guessed.
        guessed = set()
        failures = 0
        for char in self._guesses:
            if char in self._word and char not in guessed:
                guessed.add(char)
            else:
                failures += 1
        return failures
